{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "O comprimento da circunferência dá o raio. Os vértices do quadrado estão na circunferência, então a diagonal do quadrado é o diâmetro. A soma das áreas dos quatro segmentos circulares (as partes verdes) é a área do círculo menos a área do quadrado.",
   "motivo": "Frases mais curtas e diretas; deixa claro que as partes verdes são os segmentos."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "comprimento = 2 × π × r, logo r = comprimento ÷ (2π)",
    "área do círculo = π × r²",
    "diâmetro = 2 × r",
    "área do quadrado = diagonal² ÷ 2 (vem de d = L√2, então d² = 2L²)"
   ],
   "motivo": "Explica de onde vem a fórmula da área pela diagonal e inclui o diâmetro, usado nos passos."
  },
  {
   "campo": "resolucao.passos[0].conta",
   "depois": "2πr = 4√2 π → r = 2√2",
   "motivo": "Mostra o resultado do passo; a conta antiga parava na equação."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "(2√2)² = 2² × (√2)² = 4 × 2 = 8. O quadrado vale para o 2 e também para a raiz.",
   "motivo": "A frase antiga (\"tira a raiz e eleva também o 2\") era confusa."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "A diagonal é L√2, então L√2 = 4√2 e L = 4. A área é 4 × 4 = 16, igual a 32 ÷ 2.",
   "motivo": "Deixa o raciocínio na ordem natural e a conferência clara."
  },
  {
   "campo": "resolucao.erradas.A",
   "depois": "8(π − 1) = 8π − 8 subtrai só 8 do círculo. O quadrado vale 16 (lado 4), não 8. O valor 8 aparece se alguém confunde a área do quadrado com a metade dele.",
   "motivo": "A explicação antiga era enrolada (lado 2√2 igual ao raio é incorreto na afirmação: o lado 2√2 não é o raio...). Reescrita focada no que faltou: a área real do quadrado."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "4π − 2 não confere: 4π seria o círculo de raio 2, mas o raio é 2√2 e o círculo vale 8π. Além disso, o quadrado vale 16, não 2.",
   "motivo": "Mais direta, com o teste que derruba a alternativa."
  },
  {
   "campo": "resolucao.armadilha",
   "depois": "Elevar só parte do raio ao quadrado ((2√2)² é 8, não 4√2) ou tomar a diagonal do quadrado como se fosse o lado.",
   "motivo": "A versão antiga citava 'raio pelo lado', menos ligada aos erros reais das alternativas."
  },
  {
   "campo": "resolucao.checagem",
   "depois": "Em números: 8π ≈ 25,13 e 25,13 − 16 ≈ 9,13. O quadrado ocupa 16 ÷ 25,13 ≈ 64% do círculo. Isso é plausível, pois a razão é 2/π ≈ 0,64. E 8(π − 2) ≈ 8 × 1,14 ≈ 9,13.",
   "motivo": "Texto mais simples; usa 'razão' e não 'cerca de' repetido."
  },
  {
   "campo": "quadro",
   "depois": [
    {"linha": "2πr = 4√2 π", "nota": "comprimento da circunferência"},
    {"linha": "r = \\frac{4√2 π}{2π}", "nota": "o 2π passa dividindo", "mov": [{"termo": "2π", "de": "esquerda", "para": "denominador", "vira": "2π", "como": "passa dividindo"}]},
    {"linha": "r = 2√2", "nota": "4 ÷ 2 = 2 e o π cancela", "destaque": "2√2"},
    {"linha": "A_círculo = π × (2√2)²", "nota": "área do círculo"},
    {"linha": "A_círculo = π × 8 = 8π", "nota": "(2√2)² = 4 × 2 = 8"},
    {"linha": "d = 2r = 4√2", "nota": "diagonal do quadrado = diâmetro"},
    {"linha": "A_quadrado = \\frac{(4√2)²}{2}", "nota": "área = diagonal² ÷ 2"},
    {"linha": "A_quadrado = \\frac{32}{2} = 16", "nota": "(4√2)² = 16 × 2 = 32"},
    {"linha": "A_verde = 8π − 16", "nota": "círculo menos quadrado"},
    {"linha": "A_verde = 8(π − 2)", "nota": "8 em evidência", "destaque": "8(π − 2)"}
   ],
   "motivo": "Frações empilhadas em \\frac, conforme o padrão da matéria."
  }
 ],
 "didatica_alertas": [
  "Nível no JSON (4) difere do informado na classificação (5); tema/conteúdo (M08/M08.5) também diferem de M12.4. Não alterei."
 ],
 "didatica_ok": true
}
